def quick_sort(arr):
    """Sayı listesini Hızlı Sıralama algoritmasını kullanarak artan düzende sıralayın"""
    if len(arr) == 0:
        return []

    pivot = arr[0]
    left_arr = [x for x in arr if x < pivot]
    right_arr = [x for x in arr if x > pivot]
    return quick_sort(left_arr) + [pivot] + quick_sort(right_arr)

