```cpp
#include <iostream>
using namespace std;

// Bir düğüm için yapı
struct Node {
    int veri;
    Node* sonraki;
};

// Yeni bir düğüm oluşturma işlevi
Node* yeniDugum(int veri) {
    Node* dugum = new Node;
    dugum->veri = veri;
    dugum->sonraki = nullptr;
    return dugum;
}

// Bağlantılı listeyi tekrarlama yoluyla tersine çevirme işlevi
Node* listeyiTersineCevir(Node* suanki, Node* onceki) {
    // Temel durum: Geçerli düğüm boşsa, önceki düğümü döndür
    if (suanki == nullptr)
        return onceki;

    Node* sonraki = suanki->sonraki; // Sonraki düğümü depola
    suanki->sonraki = onceki; // Geçerli düğümün işaretçisini tersine çevir

    // Kalan bağlantılı liste için işlevi tekrarlı olarak çağır
    return listeyiTersineCevir(sonraki, suanki);
}

// Bağlantılı listeyi yazdırma işlevi
void listeyiYazdir(Node* dugum) {
    while (dugum != nullptr) {
        cout << dugum->veri << " ";
        dugum = dugum->sonraki;
    }
    cout << endl;
}

int main() {
    Node* kafa = yeniDugum(1);
    kafa->sonraki = yeniDugum(2);
    kafa->sonraki->sonraki = yeniDugum(3);
    kafa->sonraki->sonraki->sonraki = yeniDugum(4);
    kafa->sonraki->sonraki->sonraki->sonraki = yeniDugum(5);

    cout << "Orijinal Bağlantılı Liste: ";
    listeyiYazdir(kafa);

    kafa = listeyiTersineCevir(kafa, nullptr);

    cout << "Tersine Çevrilmiş Bağlantılı Liste: ";
    listeyiYazdir(kafa);

    return 0;
}
```

Bu kodda `listeyiTersineCevir` işlevi verilen bağlantılı listeyi tekrarlı olarak tersine çevirir. İki parametre alır - `suanki` ve `onceki`. `Suanki` geçerli düğümü, `onceki` ise önceki düğümü temsil eder. İşlev, bir sonraki düğümü geçerli düğüm ve geçerli düğümü önceki düğüm olarak geçirerek kendini tekrarlı olarak çağırır. Temel durum, geçerli düğümün boş olduğu ve bu durumda önceki düğümün döndürüldüğü durumdur.

