        Random rand = new Random();
        int num = rand.nextInt(1000) + 1; // 1 ile 1000 arasnda rasgele bir say retir

        System.out.println("Rasgele say: " + num);

        if (isPrime(num) && isPrime(sumOfDigits(num))) {
            System.out.println("Say kuvvetli asal saydr.");
        } else {
            System.out.println("Say kuvvetli asal say deildir.");
        }
    }

    // Bir saynn asal olup olmadn kontrol eden fonksiyon
    public static boolean isPrime(int num) {
        if (num <= 1) {
            return false;
        }

        // Saynn 2'den sqrt(say) aralndaki herhangi bir sayya Blnp blnmediini kontrol eder
        for (int i = 2; i <= Math.sqrt(num); i++) {
            if (num % i == 0) {
                return false;
            }
        }

        return true;
    }

    // Saynn rakamlarnn toplamn hesaplayan fonksiyon
    public static int sumOfDigits(int num) {
        int sum = 0;

        while (num > 0) {
            sum += num % 10; // son rakam toplaya ekler
            num /= 10; // son rakam siler
        }

        return sum;
    }
}

