```python
import math

def asal_mi(sayi):
    if sayi < 2:
        return False
    for i in range(2, int(math.sqrt(sayi)) + 1):
        if sayi % i == 0:
            return False
    return True

def mükemmel_kare_mi(sayi):
    kök = int(math.sqrt(sayi))
    return kök * kök == sayi

def asal_toplam_ikilileri_üret(sayilar):
    ikililer = []
    for i in range(len(sayilar)):
        for j in range(i + 1, len(sayilar)):
            ikili_toplami = sayilar[i] + sayilar[j]
            if asal_mi(ikili_toplami) and mükemmel_kare_mi(ikili_toplami):
                ikililer.append((sayilar[i], sayilar[j]))

    ikililer.sort()
    return ikililer

# Örnek kullanım:
sayilar = [1, 2, 3, 4, 5, 6]
ikililer = asal_toplam_ikilileri_üret(sayilar)
print(ikililer)
```

