function findKthSmallestPrime(arr, k) {
  let primes = [];

  for (let num of arr) {
    let isPrime = true;

    for (let i = 2; i <= Math.sqrt(num); i++) {
      if (num % i === 0) {
        isPrime = false;
        break;
      }
    }

    if (isPrime) {
      primes.push(num);

      if (primes.length === k) {
        return num;
      }
    }
