#include <iostream>
#include <string>

bool palindromikMi(const std::string& str) {
    int baslangic = 0;
    int bitis = str.length() - 1;
    while (baslangic < bitis) {
        if (str[baslangic] != str[bitis])
            return false;
        baslangic++;
        bitis--;
    }
    return true;
}

bool gecerliAltDiziMi(const std::string& str) {
    if (str.length() < 5)
        return false;

    bool rakamBulundu = false;
    for (char ch : str) {
        if (isdigit(ch))
            rakamBulundu = true;
    }
    if (!rakamBulundu)
        return false;

    for (int i = 1; i < str.length(); i++) {
        if (str[i] <= str[i - 1])
            return false;
    }
    return true;
}

std::string enUzunOrtakAltDiziyiBul(const std::string& str1, const std::string& str2) {
    int maksimumUzunluk = 0;
    int maksimumBaslangic = 0;

    int n = str1.length();
    int m = str2.length();

    int dp[n + 1][m + 1];
    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= m; j++) {
            if (i == 0 || j == 0)
                dp[i][j] = 0;
            else if (str1[i - 1] == str2[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
                if (dp[i][j] > maksimumUzunluk && gecerliAltDiziMi(str1.substr(i - dp[i][j], dp[i][j]))) {
                    maksimumUzunluk = dp[i][j];
                    maksimumBaslangic = i - dp[i][j];
                }
            } else
                dp[i][j] = 0;
        }
    }

    return str1.substr(maksimumBaslangic, maksimumUzunluk);
}

int main() {
