    std::cout << "İlk diziyi girin: ";
    std::cin >> str1;
    std::cout << "İkinci diziyi girin: ";
    std::cin >> str2;

    std::string enUzunOrtakAltDizi = enUzunOrtakAltDiziyiBul(str1, str2);

    if (enUzunOrtakAltDizi.empty())
        std::cout << "Ortak alt dize bulunamadı.";
    else
        std::cout << "En uzun ortak alt dize: " << enUzunOrtakAltDizi;

