        self.value = value
        self.children = []

def print_nary_trees(numNodes, k):
    # Helper function to recursively generate all possible n-ary trees
    def generate_trees(num_nodes, max_children):
        if num_nodes == 0:
            return [None]

        trees = []
        for i in range(1, min(num_nodes, max_children) + 1):
            # Generate all possible subtrees with i nodes
            left_subtrees = generate_trees(i, max_children)
            right_subtrees = generate_trees(num_nodes - i, max_children)

            # Combine each left subtree with each right subtree
            for left_subtree in left_subtrees:
                for right_subtree in right_subtrees:
                    root = Node(num_nodes)
                    root.children = [left_subtree] + [Node(j) for j in range(num_nodes - i + 1, num_nodes + 1)]
                    if right_subtree is not None:
                        root.children.append(right_subtree)
                    trees.append(root)

        return trees

    trees = generate_trees(numNodes, k)
    for tree in trees:
        print_tree(tree)

def print_tree(root):
    # Helper function to print the tree
    if root is None:
        return
    print(root.value, end=" ")
    for child in root.children:
        print_tree(child)
    print()

# Example usage
