import time

def solve_sudoku(board, time_limit):
    start_time = time.time()
    n = len(board)
    empty_cells = find_empty_cells(board)

    if backtracking(board, empty_cells, n, start_time, time_limit):
        return board
    else:
        return None

def backtracking(board, empty_cells, n, start_time, time_limit):
    if time.time() - start_time >= time_limit:
        return False

    if not empty_cells:
        return True

    row, col = empty_cells.pop(0)
    for num in range(1, n+1):
        if is_valid(board, row, col, num):
            board[row][col] = num
            if backtracking(board, empty_cells, n, start_time, time_limit):
                return True
            board[row][col] = 0

    empty_cells.insert(0, (row, col))
    return False

def is_valid(board, row, col, num):
    n = len(board)
    # Check row and column
    for i in range(n):
        if board[row][i] == num or board[i][col] == num:
            return False
    # Check box
    box_size = int(n ** 0.5)
    start_row = (row // box_size) * box_size
    start_col = (col // box_size) * box_size
    for i in range(start_row, start_row + box_size):
        for j in range(start_col, start_col + box_size):
            if board[i][j] == num:
                return False
    return True

def find_empty_cells(board):
    empty_cells = []
    for i in range(len(board)):
        for j in range(len(board)):
            if board[i][j] == 0:
                empty_cells.append((i, j))
    return empty_cells
